package com.osrsassistant;

import lombok.Data;

import java.util.ArrayList;
import java.util.List;

@Data
public class Checklist
{
	private final String title;
	private final List<ChecklistGroup> groups;

	public Checklist(String title)
	{
		this.title = title;
		this.groups = new ArrayList<>();
	}

	public void addGroup(ChecklistGroup group)
	{
		groups.add(group);
	}

	/**
	 * Get the first uncompleted group.
	 */
	public ChecklistGroup getCurrentGroup()
	{
		for (ChecklistGroup group : groups)
		{
			if (!group.isCompleted())
			{
				return group;
			}
		}
		return null;
	}

	public int getCurrentGroupIndex()
	{
		for (int i = 0; i < groups.size(); i++)
		{
			if (!groups.get(i).isCompleted())
			{
				return i;
			}
		}
		return groups.size();
	}

	/**
	 * Get the active substep — the first uncompleted substep in the first uncompleted group.
	 */
	public ChecklistStep getActiveStep()
	{
		ChecklistGroup group = getCurrentGroup();
		return group != null ? group.getCurrentSubstep() : null;
	}

	public boolean isComplete()
	{
		return !groups.isEmpty() && groups.stream().allMatch(ChecklistGroup::isCompleted);
	}

	public int totalSteps()
	{
		return groups.stream().mapToInt(g -> g.getSubsteps().size()).sum();
	}

	public int completedSteps()
	{
		return groups.stream().mapToInt(ChecklistGroup::completedCount).sum();
	}
}

package com.osrsassistant;

import lombok.Data;

import java.util.ArrayList;
import java.util.List;

@Data
public class ChecklistGroup
{
	private final String title;
	private final List<ChecklistStep> substeps;

	// Optional group-level navigation (where to go when this group starts)
	private String gotoName;
	private int gotoX = -1;
	private int gotoY = -1;

	public ChecklistGroup(String title)
	{
		this.title = title;
		this.substeps = new ArrayList<>();
	}

	public void addStep(ChecklistStep step)
	{
		substeps.add(step);
	}

	public boolean isCompleted()
	{
		return !substeps.isEmpty() && substeps.stream().allMatch(ChecklistStep::isCompleted);
	}

	public ChecklistStep getCurrentSubstep()
	{
		for (ChecklistStep step : substeps)
		{
			if (!step.isCompleted())
			{
				return step;
			}
		}
		return null;
	}

	public int getCurrentSubstepIndex()
	{
		for (int i = 0; i < substeps.size(); i++)
		{
			if (!substeps.get(i).isCompleted())
			{
				return i;
			}
		}
		return substeps.size();
	}

	public int completedCount()
	{
		return (int) substeps.stream().filter(ChecklistStep::isCompleted).count();
	}

	public boolean hasGoto()
	{
		return gotoX >= 0 && gotoY >= 0;
	}
}

package com.osrsassistant;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;

import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;

@Slf4j
public class ChecklistManager
{
	private final Client client;
	private final ItemManager itemManager;
	private final CopyOnWriteArrayList<Checklist> activeChecklists = new CopyOnWriteArrayList<>();

	private StepResolver stepResolver;
	private volatile MicroAction currentMicroAction;

	// Index of the checklist that drives navigation. -1 = none.
	private int trackedIndex = 0;

	public ChecklistManager(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	public int getTrackedIndex()
	{
		return trackedIndex;
	}

	public void setTrackedIndex(int index)
	{
		if (index >= -1 && index < activeChecklists.size())
		{
			trackedIndex = index;
		}
	}

	public Checklist getTrackedChecklist()
	{
		if (trackedIndex >= 0 && trackedIndex < activeChecklists.size())
		{
			return activeChecklists.get(trackedIndex);
		}
		return null;
	}

	public void setStepResolver(StepResolver resolver)
	{
		this.stepResolver = resolver;
	}

	public MicroAction getCurrentMicroAction()
	{
		return currentMicroAction;
	}

	public void addChecklist(Checklist checklist)
	{
		activeChecklists.add(checklist);
		log.info("Checklist added: {} ({} groups, {} total steps)",
			checklist.getTitle(), checklist.getGroups().size(), checklist.totalSteps());
	}

	/**
	 * Add a checklist and immediately track it (focus navigation on it).
	 */
	public void addAndTrack(Checklist checklist)
	{
		activeChecklists.add(checklist);
		trackedIndex = activeChecklists.size() - 1;
		log.info("Checklist added and tracked: {}", checklist.getTitle());
	}

	public void setChecklist(Checklist checklist)
	{
		activeChecklists.clear();
		addChecklist(checklist);
		trackedIndex = 0;
	}

	public void removeChecklist(int index)
	{
		if (index >= 0 && index < activeChecklists.size())
		{
			Checklist removed = activeChecklists.remove(index);
			log.info("Checklist removed: {}", removed.getTitle());

			// Adjust tracked index
			if (activeChecklists.isEmpty())
			{
				trackedIndex = -1;
			}
			else if (index == trackedIndex)
			{
				trackedIndex = Math.min(trackedIndex, activeChecklists.size() - 1);
			}
			else if (index < trackedIndex)
			{
				trackedIndex--;
			}
		}
	}

	public void removeChecklist(Checklist checklist)
	{
		int index = activeChecklists.indexOf(checklist);
		if (index >= 0)
		{
			removeChecklist(index);
		}
	}

	public void clear()
	{
		activeChecklists.clear();
		trackedIndex = -1;
		log.info("All checklists cleared");
	}

	public List<Checklist> getActiveChecklists()
	{
		return activeChecklists;
	}

	/**
	 * Returns the first checklist for backwards compatibility.
	 */
	public Checklist getActiveChecklist()
	{
		return activeChecklists.isEmpty() ? null : activeChecklists.get(0);
	}

	public boolean hasChecklist()
	{
		return !activeChecklists.isEmpty();
	}

	/**
	 * Called every game tick. Checks the active step in ALL checklists.
	 * Step completion is permanent — once a step is completed it stays
	 * completed even if the condition is no longer satisfied (e.g. items
	 * used on the next step). Use Undo for manual revert.
	 * Returns true if any step completed this tick.
	 */
	public boolean onGameTick()
	{
		boolean anyCompleted = false;

		for (Checklist checklist : activeChecklists)
		{
			ChecklistStep active = checklist.getActiveStep();
			if (active == null || active.isCompleted())
			{
				continue;
			}

			StepCondition cond = active.getCondition();
			if (cond != null && cond.check(client, itemManager))
			{
				active.setCompleted(true);
				log.info("Step completed: {}", active.getDescription());
				anyCompleted = true;
			}
		}

		// Remove completed checklists and adjust tracked index
		for (int i = activeChecklists.size() - 1; i >= 0; i--)
		{
			if (activeChecklists.get(i).isComplete())
			{
				activeChecklists.remove(i);
				if (i == trackedIndex)
				{
					// Tracked checklist completed — track next available or -1
					trackedIndex = activeChecklists.isEmpty() ? -1 : Math.min(trackedIndex, activeChecklists.size() - 1);
				}
				else if (i < trackedIndex)
				{
					trackedIndex--;
				}
			}
		}

		// Resolve micro-action for current active step
		resolveMicroAction();

		return anyCompleted;
	}

	/**
	 * Resolve the current micro-action from the tracked checklist's active step.
	 */
	private void resolveMicroAction()
	{
		resolveMicroAction(null);
	}

	/**
	 * Resolve micro-action with full player context.
	 * Only resolves for the tracked checklist.
	 */
	public void resolveMicroAction(PlayerContext ctx)
	{
		if (stepResolver == null)
		{
			currentMicroAction = null;
			return;
		}

		Checklist tracked = getTrackedChecklist();
		if (tracked != null)
		{
			ChecklistStep active = tracked.getActiveStep();
			if (active != null && !active.isCompleted())
			{
				currentMicroAction = stepResolver.resolve(active, ctx);
				return;
			}
		}
		currentMicroAction = null;
	}

	/**
	 * Called when a chat message arrives. Checks active step in ALL checklists.
	 */
	public boolean onChatMessage(String message)
	{
		boolean anyCompleted = false;
		for (Checklist checklist : activeChecklists)
		{
			ChecklistStep active = checklist.getActiveStep();
			if (active == null || active.isCompleted())
			{
				continue;
			}

			StepCondition cond = active.getCondition();
			if (cond == null) continue;

			cond.onChatMessage(message);
			if (cond.check(client, itemManager))
			{
				active.setCompleted(true);
				log.info("Step completed (chat): {}", active.getDescription());
				anyCompleted = true;
			}
		}
		return anyCompleted;
	}

	/**
	 * Called when XP changes. Routes to active step's xp: condition.
	 */
	public boolean onXpChanged(Skill skill, int currentXp)
	{
		boolean anyCompleted = false;
		for (Checklist checklist : activeChecklists)
		{
			ChecklistStep active = checklist.getActiveStep();
			if (active == null || active.isCompleted())
			{
				continue;
			}

			StepCondition cond = active.getCondition();
			if (cond == null) continue;

			cond.onXpChanged(skill, currentXp);
			if (cond.check(client, itemManager))
			{
				active.setCompleted(true);
				log.info("Step completed (xp): {}", active.getDescription());
				anyCompleted = true;
			}
		}
		return anyCompleted;
	}

	/**
	 * Undo the last completed step in the given checklist.
	 */
	public boolean undoLastStep(Checklist checklist)
	{
		if (checklist == null) return false;

		// Find the last completed step before the current active step
		ChecklistStep lastCompleted = null;
		for (ChecklistGroup group : checklist.getGroups())
		{
			for (ChecklistStep step : group.getSubsteps())
			{
				if (step.isCompleted())
				{
					lastCompleted = step;
				}
			}
		}

		if (lastCompleted != null)
		{
			lastCompleted.setCompleted(false);
			if (lastCompleted.getCondition() != null)
			{
				lastCompleted.getCondition().reset();
			}
			log.info("Step undone: {}", lastCompleted.getDescription());
			return true;
		}
		return false;
	}

	/**
	 * Undo the last completed step in the first checklist.
	 */
	public boolean undoLastStep()
	{
		return !activeChecklists.isEmpty() && undoLastStep(activeChecklists.get(0));
	}

	/**
	 * Gets the current navigation step from the first checklist with one.
	 */
	public ChecklistStep getCurrentNavigationStep()
	{
		for (Checklist checklist : activeChecklists)
		{
			ChecklistStep active = checklist.getActiveStep();
			if (active != null && active.hasGoto())
			{
				return active;
			}

			ChecklistGroup group = checklist.getCurrentGroup();
			if (group != null && group.hasGoto())
			{
				ChecklistStep groupNav = new ChecklistStep(group.getTitle(), null);
				groupNav.setGotoName(group.getGotoName());
				groupNav.setGotoX(group.getGotoX());
				groupNav.setGotoY(group.getGotoY());
				return groupNav;
			}
		}
		return null;
	}
}

package com.osrsassistant;

import net.runelite.api.MenuAction;
import net.runelite.client.input.MouseListener;
import net.runelite.client.input.MouseManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

import java.awt.*;
import java.awt.event.MouseEvent;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;

public class ChecklistOverlay extends Overlay implements MouseListener
{
	private final OsrsAssistantPlugin plugin;

	private static final int MIN_W = 180;
	private static final int MAX_W = 400;
	private static final int PAD = 10;
	private static final int RESIZE_HANDLE = 12;

	// State
	private int panelWidth = 230;
	private final List<ButtonRegion> buttons = new ArrayList<>();
	private final java.util.Set<Integer> collapsedChecklists = new java.util.HashSet<>();
	private Point overlayOrigin = new Point(0, 0);
	private Point mousePos = new Point(-1, -1);
	private Dimension lastSize = new Dimension(0, 0);
	private boolean resizing = false;
	private int resizeStartX = 0;
	private int resizeStartWidth = 0;

	private static class ButtonRegion
	{
		Rectangle bounds;
		Runnable action;
		String label;

		ButtonRegion(Rectangle bounds, String label, Runnable action)
		{
			this.bounds = bounds;
			this.label = label;
			this.action = action;
		}
	}

	public ChecklistOverlay(OsrsAssistantPlugin plugin)
	{
		this.plugin = plugin;
		setPosition(OverlayPosition.TOP_LEFT);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
		setMovable(true);
	}

	public void registerMouse(MouseManager mouseManager)
	{
		mouseManager.registerMouseListener(this);
	}

	public void unregisterMouse(MouseManager mouseManager)
	{
		mouseManager.unregisterMouseListener(this);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		ChecklistManager mgr = plugin.getChecklistManager();
		if (mgr == null || !mgr.hasChecklist())
		{
			return null;
		}

		List<Checklist> checklists = mgr.getActiveChecklists();
		buttons.clear();

		// Pre-render to calculate height
		int totalHeight = renderContent(null, checklists);

		// Actual render
		BufferedImage img = new BufferedImage(panelWidth, totalHeight, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = img.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		// Background
		g.setColor(new Color(20, 20, 24, 240));
		g.fillRoundRect(0, 0, panelWidth, totalHeight, 10, 10);
		g.setColor(Theme.BORDER);
		g.drawRoundRect(0, 0, panelWidth - 1, totalHeight - 1, 10, 10);

		// Resize handle (bottom-right corner)
		int rhX = panelWidth - RESIZE_HANDLE - 2;
		int rhY = totalHeight - RESIZE_HANDLE - 2;
		g.setColor(Theme.TEXT_MUTED);
		for (int i = 0; i < 3; i++)
		{
			int offset = i * 4;
			g.drawLine(rhX + offset + 4, rhY + RESIZE_HANDLE, rhX + RESIZE_HANDLE, rhY + offset + 4);
		}

		buttons.clear();
		renderContent(g, checklists);

		g.dispose();

		// Store origin for hit-testing
		Rectangle bounds = getBounds();
		if (bounds != null)
		{
			overlayOrigin = bounds.getLocation();
		}

		graphics.drawImage(img, 0, 0, null);
		lastSize = new Dimension(panelWidth, totalHeight);
		return lastSize;
	}

	private int renderContent(Graphics2D g, List<Checklist> checklists)
	{
		int y = PAD;

		for (int ci = 0; ci < checklists.size(); ci++)
		{
			Checklist cl = checklists.get(ci);
			if (ci > 0)
			{
				y += 4;
				if (g != null)
				{
					g.setColor(Theme.BORDER);
					g.drawLine(PAD, y, panelWidth - PAD, y);
				}
				y += 4;
			}
			y = renderChecklist(g, cl, ci, y);
		}

		return y + PAD;
	}

	private int renderChecklist(Graphics2D g, Checklist cl, int clIndex, int y)
	{
		FontMetrics titleFm = getFm(g, Theme.SENDER);
		FontMetrics groupFm = getFm(g, Theme.SMALL_BOLD);
		FontMetrics stepFm = getFm(g, Theme.SMALL);
		FontMetrics hintFm = getFm(g, Theme.ITALIC.deriveFont(9f));

		int completed = cl.completedSteps();
		int total = cl.totalSteps();
		List<ChecklistGroup> groups = cl.getGroups();
		int currentGroupIdx = cl.getCurrentGroupIndex();

		boolean isTracked = (clIndex == plugin.getChecklistManager().getTrackedIndex());
		boolean isCollapsed = collapsedChecklists.contains(clIndex);
		final int idx = clIndex;

		// ---- Title row: [dot] Title           [fold] [X] ----
		if (g != null)
		{
			// Tracking dot
			int dotR = 4;
			int dotCY = y + titleFm.getHeight() / 2;
			g.setColor(isTracked ? Theme.SUCCESS : Theme.TEXT_MUTED);
			g.fillOval(PAD, dotCY - dotR, dotR * 2, dotR * 2);

			// Title text — clickable to track
			Rectangle titleBounds = new Rectangle(PAD, y, panelWidth - PAD * 2 - 36, titleFm.getHeight());
			boolean titleHover = titleBounds.contains(relMouse());
			g.setFont(Theme.SENDER);
			g.setColor(isTracked ? Theme.ACCENT : (titleHover ? Theme.ACCENT : Theme.TEXT_MUTED));
			g.drawString(truncate(cl.getTitle(), titleFm, panelWidth - PAD * 2 - 50), PAD + 12, y + titleFm.getAscent());
			buttons.add(new ButtonRegion(titleBounds, "track", () -> {
				plugin.getChecklistManager().setTrackedIndex(idx);
				plugin.navigateAfterChecklistChange();
			}));

			// Close [X]
			int closeX = panelWidth - PAD - 10;
			int closeY = y + 4;
			Rectangle closeBounds = new Rectangle(closeX - 4, closeY - 4, 16, 16);
			boolean closeHover = closeBounds.contains(relMouse());
			g.setColor(closeHover ? Theme.CANCEL : Theme.TEXT_MUTED);
			g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
			g.drawLine(closeX, closeY, closeX + 8, closeY + 8);
			g.drawLine(closeX + 8, closeY, closeX, closeY + 8);
			g.setStroke(new BasicStroke(1f));
			buttons.add(new ButtonRegion(closeBounds, "close", () -> {
				plugin.getChecklistManager().removeChecklist(cl);
				if (!plugin.getChecklistManager().hasChecklist()) plugin.cancelNavigation();
				else plugin.navigateAfterChecklistChange();
			}));

			// Fold toggle
			int foldX = closeX - 18;
			int foldY = closeY + 1;
			Rectangle foldBounds = new Rectangle(foldX - 2, foldY - 4, 14, 14);
			boolean foldHover = foldBounds.contains(relMouse());
			g.setColor(foldHover ? Theme.TEXT : Theme.TEXT_MUTED);
			if (isCollapsed)
			{
				int[] tx = {foldX, foldX, foldX + 6};
				int[] ty = {foldY, foldY + 8, foldY + 4};
				g.fillPolygon(tx, ty, 3);
			}
			else
			{
				int[] tx = {foldX, foldX + 8, foldX + 4};
				int[] ty = {foldY + 1, foldY + 1, foldY + 6};
				g.fillPolygon(tx, ty, 3);
			}
			buttons.add(new ButtonRegion(foldBounds, "fold", () -> {
				if (collapsedChecklists.contains(idx)) collapsedChecklists.remove(idx);
				else collapsedChecklists.add(idx);
			}));
		}
		y += titleFm.getHeight() + 6;

		// ---- Progress bar ----
		int barW = panelWidth - PAD * 2;
		String progressText = completed + " of " + total;
		if (g != null)
		{
			g.setColor(Theme.SURFACE);
			g.fillRoundRect(PAD, y, barW, 6, 3, 3);
			if (total > 0)
			{
				int fw = Math.max((int)((double) completed / total * barW), 3);
				g.setColor(isTracked ? Theme.ACCENT : Theme.TEXT_MUTED);
				g.fillRoundRect(PAD, y, fw, 6, 3, 3);
			}
			g.setFont(Theme.SMALL);
			g.setColor(Theme.TEXT_DIM);
			FontMetrics sf = g.getFontMetrics();
			g.drawString(progressText, panelWidth - PAD - sf.stringWidth(progressText), y + 6 + sf.getAscent() + 2);
		}
		y += 18;

		if (isCollapsed) return y;

		// ---- Groups ----
		for (int i = 0; i < groups.size(); i++)
		{
			ChecklistGroup group = groups.get(i);
			boolean isCurrent = (i == currentGroupIdx && !group.isCompleted());
			boolean isDone = group.isCompleted();

			if (g != null)
			{
				// Group indicator + title
				int indCY = y + groupFm.getHeight() / 2;
				if (isDone)
				{
					drawCheckmark(g, PAD + 1, indCY, 8, Theme.SUCCESS);
					g.setColor(new Color(Theme.SUCCESS.getRed(), Theme.SUCCESS.getGreen(), Theme.SUCCESS.getBlue(), 120));
				}
				else if (isCurrent)
				{
					drawArrow(g, PAD + 1, indCY, 7, Theme.ACCENT);
					g.setColor(Theme.TEXT);
				}
				else
				{
					drawCircle(g, PAD + 3, indCY, 4, Theme.TEXT_MUTED);
					g.setColor(Theme.TEXT_MUTED);
				}
				g.setFont(Theme.SMALL_BOLD);

				String title = truncate(group.getTitle(), groupFm, panelWidth - PAD * 2 - 40);
				g.drawString(title, PAD + 14, y + groupFm.getAscent());

				// Progress count for current group
				if (isCurrent)
				{
					g.setFont(Theme.SMALL);
					g.setColor(Theme.TEXT_DIM);
					String ct = group.completedCount() + "/" + group.getSubsteps().size();
					g.drawString(ct, panelWidth - PAD - g.getFontMetrics().stringWidth(ct), y + groupFm.getAscent());
				}
			}
			y += groupFm.getHeight() + 4;

			// ---- Steps (only for current group) ----
			if (isCurrent)
			{
				int currentSubIdx = group.getCurrentSubstepIndex();
				int textMaxW = panelWidth - PAD * 2 - 30;

				for (int j = 0; j < group.getSubsteps().size(); j++)
				{
					ChecklistStep step = group.getSubsteps().get(j);
					boolean subDone = step.isCompleted();
					boolean subCurrent = (j == currentSubIdx);

					String[] lines = wrapText(step.getDescription(), stepFm, textMaxW);
					int stepH = lines.length * stepFm.getHeight() + 4;

					if (g != null)
					{
						// Highlight active step
						if (subCurrent && !subDone)
						{
							g.setColor(new Color(Theme.ACCENT.getRed(), Theme.ACCENT.getGreen(), Theme.ACCENT.getBlue(), 12));
							g.fillRoundRect(PAD + 8, y, panelWidth - PAD * 2 - 8, stepH, 4, 4);
						}

						// Step indicator
						int indCY = y + stepH / 2;
						if (subDone)
						{
							drawCheckmark(g, PAD + 14, indCY, 6, Theme.SUCCESS);
						}
						else if (subCurrent)
						{
							drawArrow(g, PAD + 14, indCY, 5, Theme.ACCENT);
						}
						else
						{
							drawCircle(g, PAD + 16, indCY, 3, Theme.TEXT_MUTED);
						}

						// Step text
						g.setFont(Theme.SMALL);
						g.setColor(subDone ? Theme.TEXT_MUTED : (subCurrent ? Theme.TEXT : Theme.TEXT_DIM));
						int textX = PAD + 26;
						int textY = y + stepFm.getAscent();
						for (String line : lines)
						{
							g.drawString(line, textX, textY);
							textY += stepFm.getHeight();
						}

						// Skip link on the right for current step
						if (subCurrent && !subDone)
						{
							g.setFont(Theme.SMALL);
							int skipW = stepFm.stringWidth("skip") + 4;
							int skipTextX = panelWidth - PAD - skipW;
							int skipTextY = y + stepFm.getAscent();
							Rectangle skipBounds = new Rectangle(skipTextX - 2, y, skipW + 4, stepH);
							boolean skipHover = skipBounds.contains(relMouse());
							g.setColor(skipHover ? Theme.WARNING : Theme.TEXT_MUTED);
							g.drawString("skip", skipTextX, skipTextY);
							buttons.add(new ButtonRegion(skipBounds, "skip", () -> {
								step.setCompleted(true);
								plugin.navigateAfterChecklistChange();
							}));
						}
					}
					y += stepH;
				}

				// ---- Navigation hint ----
				MicroAction microAction = plugin.getCurrentMicroAction();
				if (microAction != null)
				{
					String hintText = "-> " + microAction.getInstruction();
					String[] hintLines = wrapText(hintText, hintFm, panelWidth - PAD * 2 - 26);
					if (g != null)
					{
						g.setFont(Theme.ITALIC.deriveFont(9f));
						switch (microAction.getType())
						{
							case NAVIGATE: g.setColor(Theme.ACCENT); break;
							case INTERACT: g.setColor(Theme.WARNING); break;
							default: g.setColor(Theme.TEXT_DIM); break;
						}
						for (String line : hintLines)
						{
							g.drawString(line, PAD + 26, y + hintFm.getAscent());
							y += hintFm.getHeight();
						}
					}
					else
					{
						y += hintLines.length * hintFm.getHeight();
					}
					y += 4;
				}
				else if (plugin.isNavigating())
				{
					if (g != null)
					{
						g.setFont(Theme.ITALIC.deriveFont(9f));
						g.setColor(Theme.ACCENT);
						String navName = plugin.getNavigationName();
						int dist = plugin.getNavigationDistance();
						String navText = "-> " + (navName != null ? navName : "?");
						if (dist >= 0) navText += " (" + dist + " tiles)";
						g.drawString(navText, PAD + 26, y + hintFm.getAscent());
					}
					y += hintFm.getHeight() + 4;
				}

				// Undo link (small, inline)
				if (g != null)
				{
					g.setFont(Theme.SMALL);
					Rectangle undoBounds = new Rectangle(PAD + 26, y, stepFm.stringWidth("undo"), stepFm.getHeight());
					boolean undoHover = undoBounds.contains(relMouse());
					g.setColor(undoHover ? Theme.TEXT : Theme.TEXT_MUTED);
					g.drawString("undo", PAD + 26, y + stepFm.getAscent());
					buttons.add(new ButtonRegion(undoBounds, "undo", () -> {
						plugin.getChecklistManager().undoLastStep(cl);
						plugin.navigateAfterChecklistChange();
					}));
				}
				y += stepFm.getHeight() + 4;
			}
		}

		return y;
	}

	private Point relMouse()
	{
		return new Point(mousePos.x - overlayOrigin.x, mousePos.y - overlayOrigin.y);
	}

	private String truncate(String text, FontMetrics fm, int maxW)
	{
		if (fm.stringWidth(text) <= maxW) return text;
		while (text.length() > 3 && fm.stringWidth(text + "..") > maxW)
			text = text.substring(0, text.length() - 1);
		return text + "..";
	}

	private String[] wrapText(String text, FontMetrics fm, int maxW)
	{
		if (fm.stringWidth(text) <= maxW) return new String[]{text};
		List<String> lines = new ArrayList<>();
		StringBuilder cur = new StringBuilder();
		for (String word : text.split(" "))
		{
			String test = cur.length() == 0 ? word : cur + " " + word;
			if (fm.stringWidth(test) > maxW && cur.length() > 0)
			{
				lines.add(cur.toString());
				cur = new StringBuilder(word);
			}
			else
			{
				cur = new StringBuilder(test);
			}
		}
		if (cur.length() > 0) lines.add(cur.toString());
		return lines.toArray(new String[0]);
	}

	private FontMetrics getFm(Graphics2D g, Font font)
	{
		if (g != null)
		{
			g.setFont(font);
			return g.getFontMetrics();
		}
		BufferedImage tmp = new BufferedImage(1, 1, BufferedImage.TYPE_INT_ARGB);
		Graphics2D tg = tmp.createGraphics();
		tg.setFont(font);
		FontMetrics fm = tg.getFontMetrics();
		tg.dispose();
		return fm;
	}

	// -- Shape drawing helpers (no unicode dependency) --

	private void drawCheckmark(Graphics2D g, int x, int cy, int size, Color color)
	{
		g.setColor(color);
		g.setStroke(new BasicStroke(1.5f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		int half = size / 2;
		g.drawLine(x, cy, x + half, cy + half);
		g.drawLine(x + half, cy + half, x + size, cy - half);
		g.setStroke(new BasicStroke(1f));
	}

	private void drawArrow(Graphics2D g, int x, int cy, int size, Color color)
	{
		g.setColor(color);
		int half = size / 2;
		int[] ax = {x, x, x + size};
		int[] ay = {cy - half, cy + half, cy};
		g.fillPolygon(ax, ay, 3);
	}

	private void drawCircle(Graphics2D g, int cx, int cy, int radius, Color color)
	{
		g.setColor(color);
		g.drawOval(cx - radius, cy - radius, radius * 2, radius * 2);
	}

	// -- Mouse handling for button clicks --

	@Override
	public MouseEvent mouseClicked(MouseEvent e)
	{
		Point click = new Point(e.getX() - overlayOrigin.x, e.getY() - overlayOrigin.y);
		for (ButtonRegion btn : buttons)
		{
			if (btn.bounds.contains(click))
			{
				btn.action.run();
				e.consume();
				return e;
			}
		}
		return e;
	}

	@Override
	public MouseEvent mousePressed(MouseEvent e)
	{
		Point rel = new Point(e.getX() - overlayOrigin.x, e.getY() - overlayOrigin.y);

		// Block ALL clicks inside the overlay from reaching the game
		if (rel.x >= 0 && rel.x < lastSize.width && rel.y >= 0 && rel.y < lastSize.height)
		{
			// Check resize handle first
			if (rel.x >= lastSize.width - RESIZE_HANDLE - 4 && rel.y >= lastSize.height - RESIZE_HANDLE - 4)
			{
				resizing = true;
				resizeStartX = e.getX();
				resizeStartWidth = panelWidth;
			}
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseReleased(MouseEvent e)
	{
		if (resizing)
		{
			resizing = false;
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseEntered(MouseEvent e) { return e; }

	@Override
	public MouseEvent mouseExited(MouseEvent e) { return e; }

	@Override
	public MouseEvent mouseDragged(MouseEvent e)
	{
		if (resizing)
		{
			int delta = e.getX() - resizeStartX;
			panelWidth = Math.max(MIN_W, Math.min(MAX_W, resizeStartWidth + delta));
			e.consume();
		}
		return e;
	}

	@Override
	public MouseEvent mouseMoved(MouseEvent e)
	{
		mousePos = e.getPoint();
		return e;
	}
}

package com.osrsassistant;

import lombok.extern.slf4j.Slf4j;

import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Parses checklist blocks with groups and steps from AI response.
 *
 * Format:
 * {checklist:Title}
 * {group:Group Title|goto:Location}
 * {step:Description|condition|goto:Location}
 * {/group}
 * {/checklist}
 *
 * Standalone {step:} outside a group creates a single-step group (backward compatible).
 */
@Slf4j
public class ChecklistParser
{
	private static final Pattern CHECKLIST_BLOCK = Pattern.compile(
		"\\{checklist:([^}]+)\\}(.*?)\\{/checklist\\}",
		Pattern.DOTALL
	);

	private static final Pattern GROUP_OPEN = Pattern.compile(
		"\\{group:((?:[^{}]|\\{[^}]*\\})*)\\}"
	);

	private static final Pattern GROUP_CLOSE = Pattern.compile(
		"\\{/group\\}"
	);

	private static final Pattern STEP_PATTERN = Pattern.compile(
		"\\{step:((?:[^{}]|\\{[^}]*\\})*)\\}"
	);

	public static Checklist parse(String text)
	{
		Matcher blockMatcher = CHECKLIST_BLOCK.matcher(text);
		if (!blockMatcher.find())
		{
			return null;
		}

		String title = blockMatcher.group(1).trim();
		String body = blockMatcher.group(2);

		Checklist checklist = new Checklist(title);
		parseBody(body, checklist);

		return checklist.getGroups().isEmpty() ? null : checklist;
	}

	private static void parseBody(String body, Checklist checklist)
	{
		int pos = 0;
		ChecklistGroup currentGroup = null;

		while (pos < body.length())
		{
			// Try to match {group:...} at current position
			Matcher groupOpen = GROUP_OPEN.matcher(body);
			Matcher groupClose = GROUP_CLOSE.matcher(body);
			Matcher stepMatch = STEP_PATTERN.matcher(body);

			int nextGroupOpen = findNext(groupOpen, pos);
			int nextGroupClose = findNext(groupClose, pos);
			int nextStep = findNext(stepMatch, pos);

			// Find the earliest match
			int earliest = Integer.MAX_VALUE;
			if (nextGroupOpen >= 0) earliest = Math.min(earliest, nextGroupOpen);
			if (nextGroupClose >= 0) earliest = Math.min(earliest, nextGroupClose);
			if (nextStep >= 0) earliest = Math.min(earliest, nextStep);

			if (earliest == Integer.MAX_VALUE)
			{
				break; // No more tags
			}

			if (nextGroupOpen == earliest)
			{
				// Start a new group
				groupOpen.find(pos);
				String groupContent = groupOpen.group(1);
				currentGroup = parseGroupHeader(groupContent);
				pos = groupOpen.end();
			}
			else if (nextGroupClose == earliest)
			{
				// Close current group
				groupClose.find(pos);
				if (currentGroup != null && !currentGroup.getSubsteps().isEmpty())
				{
					checklist.addGroup(currentGroup);
				}
				currentGroup = null;
				pos = groupClose.end();
			}
			else if (nextStep == earliest)
			{
				// Parse a step
				stepMatch.find(pos);
				ChecklistStep step = parseStep(stepMatch.group(1));
				pos = stepMatch.end();

				if (step == null)
				{
					continue;
				}

				if (currentGroup != null)
				{
					// Step inside a group
					currentGroup.addStep(step);
				}
				else
				{
					// Standalone step — wrap in a single-step group
					ChecklistGroup wrapper = new ChecklistGroup(step.getDescription());
					wrapper.setGotoName(step.getGotoName());
					wrapper.setGotoX(step.getGotoX());
					wrapper.setGotoY(step.getGotoY());
					wrapper.addStep(step);
					checklist.addGroup(wrapper);
				}
			}
		}

		// Close any unclosed group
		if (currentGroup != null && !currentGroup.getSubsteps().isEmpty())
		{
			checklist.addGroup(currentGroup);
		}
	}

	private static int findNext(Matcher matcher, int from)
	{
		if (matcher.find(from))
		{
			return matcher.start();
		}
		return -1;
	}

	private static ChecklistGroup parseGroupHeader(String content)
	{
		// Split by | — first part is title, rest is goto
		String[] parts = content.split("\\|");
		String title = cleanDescription(parts[0]);
		ChecklistGroup group = new ChecklistGroup(title);

		for (int i = 1; i < parts.length; i++)
		{
			String part = parts[i].trim();
			if (part.startsWith("goto:"))
			{
				parseGoto(part, group);
			}
		}

		return group;
	}

	private static ChecklistStep parseStep(String content)
	{
		String[] parts = content.split("\\|");
		if (parts.length < 2)
		{
			return null;
		}

		String description = cleanDescription(parts[0]);
		StepCondition condition = null;
		String gotoName = null;
		int gotoX = -1, gotoY = -1;

		for (int i = 1; i < parts.length; i++)
		{
			String part = parts[i].trim();

			if (part.startsWith("goto:"))
			{
				String gotoStr = part.substring(5);
				String[] gotoParts = gotoStr.split(":");
				gotoName = gotoParts[0].trim();
				if (gotoParts.length >= 3)
				{
					try
					{
						gotoX = Integer.parseInt(gotoParts[1].trim());
						gotoY = Integer.parseInt(gotoParts[2].trim());
					}
					catch (NumberFormatException e)
					{
						// ignore
					}
				}
			}
			else if (condition == null)
			{
				condition = StepCondition.parse(part);
			}
		}

		if (condition == null)
		{
			return null;
		}

		ChecklistStep step = new ChecklistStep(description, condition);
		step.setGotoName(gotoName);
		step.setGotoX(gotoX);
		step.setGotoY(gotoY);

		if (gotoName != null && (gotoX < 0 || gotoY < 0))
		{
			log.warn("Step goto '{}' has no coordinates — backend failed to resolve", gotoName);
		}

		return step;
	}

	private static void parseGoto(String gotoPart, ChecklistGroup group)
	{
		String gotoStr = gotoPart.substring(5);
		String[] parts = gotoStr.split(":");
		String name = parts[0].trim();
		group.setGotoName(name);
		if (parts.length >= 3)
		{
			try
			{
				group.setGotoX(Integer.parseInt(parts[1].trim()));
				group.setGotoY(Integer.parseInt(parts[2].trim()));
			}
			catch (NumberFormatException e)
			{
				log.warn("Group goto '{}' has invalid coordinates: {}", name, gotoPart);
			}
		}
		else
		{
			log.warn("Group goto '{}' has no coordinates — backend failed to resolve", name);
		}
	}

	private static String cleanDescription(String text)
	{
		return text.trim()
			.replaceAll("\\{skill:[^}]*\\}", "")
			.replaceAll("\\{item:[^}]*\\}", "")
			.replaceAll("\\{quest:[^}]*\\}", "")
			.replaceAll("\\{loc:[^}]*\\}", "")
			.replaceAll("\\{goto:[^}]*\\}", "")
			.replaceAll("\\s{2,}", " ")
			.trim();
	}

	public static String stripChecklistTags(String text)
	{
		return CHECKLIST_BLOCK.matcher(text).replaceAll("").trim();
	}
}

package com.osrsassistant;

import lombok.Data;

@Data
public class ChecklistStep
{
	private final String description;
	private final StepCondition condition;
	private boolean completed = false;

	// Optional navigation
	private String gotoName;
	private int gotoX = -1;
	private int gotoY = -1;

	public ChecklistStep(String description, StepCondition condition)
	{
		this.description = description;
		this.condition = condition;
	}

	public boolean hasGoto()
	{
		return gotoX >= 0 && gotoY >= 0;
	}
}

