package com.osrsassistant;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.eventbus.EventBus;
import net.runelite.client.events.PluginMessage;
import net.runelite.client.plugins.PluginManager;
import net.runelite.client.plugins.Plugin;

import java.util.*;

/**
 * Manages navigation using the Shortest Path plugin.
 * If Shortest Path is not installed, navigation targets are still tracked
 * but no path is rendered.
 */
@Slf4j
public class NavigationManager
{
	private final Client client;
	private final EventBus eventBus;
	private final PluginManager pluginManager;

	private WorldPoint destination;
	private String destinationName;
	private Boolean shortestPathAvailable = null;
	private int recheckCounter = 0;

	private static final int ARRIVAL_DISTANCE = 5;
	private static final int RECHECK_INTERVAL = 100;
	private static final String SP_NAMESPACE = "shortestpath";

	public NavigationManager(Client client, EventBus eventBus, PluginManager pluginManager)
	{
		this.client = client;
		this.eventBus = eventBus;
		this.pluginManager = pluginManager;
	}

	private boolean isShortestPathAvailable()
	{
		recheckCounter++;
		if (shortestPathAvailable != null && recheckCounter < RECHECK_INTERVAL)
		{
			return shortestPathAvailable;
		}
		recheckCounter = 0;

		boolean found = false;
		try
		{
			for (Plugin plugin : pluginManager.getPlugins())
			{
				if (plugin.getClass().getSimpleName().equals("ShortestPathPlugin"))
				{
					found = pluginManager.isPluginEnabled(plugin);
					break;
				}
			}
		}
		catch (Exception e)
		{
			log.debug("Error checking for Shortest Path: {}", e.getMessage());
		}

		if (shortestPathAvailable == null || found != shortestPathAvailable)
		{
			shortestPathAvailable = found;
			if (!found)
			{
				log.info("Shortest Path plugin not found. Install it for in-game path rendering.");
			}
		}

		return shortestPathAvailable;
	}

	public void navigateTo(WorldPoint dest, String name)
	{
		this.destination = dest;
		this.destinationName = name;

		if (isShortestPathAvailable())
		{
			sendToShortestPath(dest);
		}
	}

	public void navigateTo(WorldPoint dest)
	{
		navigateTo(dest, null);
	}

	public void navigateSequential(List<WorldPoint> destinations, List<String> names)
	{
		if (destinations.isEmpty()) return;

		this.destination = destinations.get(0);
		this.destinationName = (names != null && !names.isEmpty()) ? names.get(0) : null;

		if (isShortestPathAvailable())
		{
			sendToShortestPathSequential(destinations);
		}
	}

	public void cancel()
	{
		this.destination = null;
		this.destinationName = null;

		if (shortestPathAvailable != null && shortestPathAvailable)
		{
			clearShortestPath();
		}
	}

	public boolean isNavigating()
	{
		return destination != null;
	}

	public String getDestinationName()
	{
		return destinationName;
	}

	public WorldPoint getDestination()
	{
		return destination;
	}

	public int getDistanceToDestination()
	{
		if (destination == null || client.getLocalPlayer() == null) return -1;
		return client.getLocalPlayer().getWorldLocation().distanceTo(destination);
	}

	public void update()
	{
		if (destination == null || client.getLocalPlayer() == null)
		{
			return;
		}

		int distance = client.getLocalPlayer().getWorldLocation().distanceTo(destination);
		if (distance <= ARRIVAL_DISTANCE)
		{
			log.info("Arrived at {}", destinationName);
			cancel();
		}
	}

	private void sendToShortestPath(WorldPoint target)
	{
		try
		{
			Map<String, Object> data = new HashMap<>();
			data.put("target", target);
			eventBus.post(new PluginMessage(SP_NAMESPACE, "path", data));
		}
		catch (Exception e)
		{
			log.warn("Failed to send to Shortest Path: {}", e.getMessage());
			shortestPathAvailable = false;
		}
	}

	private void sendToShortestPathSequential(List<WorldPoint> targets)
	{
		try
		{
			Set<Object> targetSet = new LinkedHashSet<>(targets);
			Map<String, Object> data = new HashMap<>();
			data.put("target", targetSet);
			eventBus.post(new PluginMessage(SP_NAMESPACE, "path", data));
		}
		catch (Exception e)
		{
			log.warn("Failed to send sequential targets: {}", e.getMessage());
			shortestPathAvailable = false;
		}
	}

	private void clearShortestPath()
	{
		try
		{
			eventBus.post(new PluginMessage(SP_NAMESPACE, "clear"));
		}
		catch (Exception e)
		{
			log.debug("Failed to clear Shortest Path: {}", e.getMessage());
		}
	}
}

package com.osrsassistant;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.coords.WorldPoint;

import java.util.ArrayList;
import java.util.List;

/**
 * Scans the loaded scene for game objects and NPCs by name.
 * Used for precise navigation to interactable things (birdhouses, banks, NPCs, etc.)
 */
@Slf4j
public class ObjectTracker
{
	private final Client client;

	public ObjectTracker(Client client)
	{
		this.client = client;
	}

	/**
	 * Find the nearest game object matching the name (case-insensitive, partial match).
	 * Returns the WorldPoint of the nearest match, or null if not found.
	 */
	public WorldPoint findNearestObject(String name)
	{
		if (client.getLocalPlayer() == null) return null;

		WorldPoint playerPos = client.getLocalPlayer().getWorldLocation();
		String searchLower = name.toLowerCase();
		WorldPoint nearest = null;
		int nearestDist = Integer.MAX_VALUE;

		try
		{
			Tile[][][] tiles = client.getTopLevelWorldView().getScene().getTiles();
			int plane = client.getPlane();

			if (tiles == null || tiles.length <= plane) return null;

			for (int x = 0; x < tiles[plane].length; x++)
			{
				for (int y = 0; y < tiles[plane][x].length; y++)
				{
					Tile tile = tiles[plane][x][y];
					if (tile == null) continue;

					// Check game objects on this tile
					for (GameObject obj : tile.getGameObjects())
					{
						if (obj == null) continue;

						String objName = getObjectName(obj.getId());
						if (objName != null && objName.toLowerCase().contains(searchLower))
						{
							WorldPoint objPos = obj.getWorldLocation();
							int dist = playerPos.distanceTo(objPos);
							if (dist < nearestDist)
							{
								nearestDist = dist;
								nearest = objPos;
							}
						}
					}

					// Check ground objects
					TileObject groundObj = tile.getGroundObject();
					if (groundObj != null)
					{
						String objName = getObjectName(groundObj.getId());
						if (objName != null && objName.toLowerCase().contains(searchLower))
						{
							WorldPoint objPos = groundObj.getWorldLocation();
							int dist = playerPos.distanceTo(objPos);
							if (dist < nearestDist)
							{
								nearestDist = dist;
								nearest = objPos;
							}
						}
					}

					// Check wall objects
					TileObject wallObj = tile.getWallObject();
					if (wallObj != null)
					{
						String objName = getObjectName(wallObj.getId());
						if (objName != null && objName.toLowerCase().contains(searchLower))
						{
							WorldPoint objPos = wallObj.getWorldLocation();
							int dist = playerPos.distanceTo(objPos);
							if (dist < nearestDist)
							{
								nearestDist = dist;
								nearest = objPos;
							}
						}
					}
				}
			}
		}
		catch (Exception e)
		{
			log.debug("Error scanning scene objects: {}", e.getMessage());
		}

		if (nearest != null)
		{
			log.debug("Found object '{}' at {} (distance: {})", name, nearest, nearestDist);
		}

		return nearest;
	}

	/**
	 * Find the nearest NPC matching the name.
	 */
	public WorldPoint findNearestNpc(String name)
	{
		if (client.getLocalPlayer() == null) return null;

		WorldPoint playerPos = client.getLocalPlayer().getWorldLocation();
		String searchLower = name.toLowerCase();
		WorldPoint nearest = null;
		int nearestDist = Integer.MAX_VALUE;

		var npcs = client.getTopLevelWorldView().npcs();
		for (NPC npc : npcs)
		{
			if (npc == null || npc.getName() == null) continue;

			if (npc.getName().toLowerCase().contains(searchLower))
			{
				WorldPoint npcPos = npc.getWorldLocation();
				int dist = playerPos.distanceTo(npcPos);
				if (dist < nearestDist)
				{
					nearestDist = dist;
					nearest = npcPos;
				}
			}
		}

		if (nearest != null)
		{
			log.debug("Found NPC '{}' at {} (distance: {})", name, nearest, nearestDist);
		}

		return nearest;
	}

	/**
	 * Find nearest object OR NPC by name.
	 */
	public WorldPoint findNearest(String name)
	{
		WorldPoint obj = findNearestObject(name);
		WorldPoint npc = findNearestNpc(name);

		if (obj == null) return npc;
		if (npc == null) return obj;

		// Return whichever is closer
		WorldPoint playerPos = client.getLocalPlayer().getWorldLocation();
		return playerPos.distanceTo(obj) <= playerPos.distanceTo(npc) ? obj : npc;
	}

	private String getObjectName(int objectId)
	{
		try
		{
			ObjectComposition comp = client.getObjectDefinition(objectId);
			if (comp == null) return null;

			// Some objects have impostor compositions (transformed objects)
			if (comp.getImpostorIds() != null)
			{
				ObjectComposition impostor = comp.getImpostor();
				if (impostor != null)
				{
					return impostor.getName();
				}
			}

			String name = comp.getName();
			return (name != null && !name.equals("null")) ? name : null;
		}
		catch (Exception e)
		{
			return null;
		}
	}
}

package com.osrsassistant;

import com.google.gson.Gson;
import lombok.extern.slf4j.Slf4j;

import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.concurrent.CompletableFuture;

@Slf4j
public class OsrsAssistantClient
{
	private final HttpClient httpClient;
	private final Gson gson;
	private volatile CompletableFuture<HttpResponse<String>> activeFuture;

	private String apiKey = "";

	public OsrsAssistantClient(Gson gson)
	{
		this.httpClient = HttpClient.newBuilder()
			.connectTimeout(Duration.ofSeconds(10))
			.build();
		this.gson = gson;
	}

	public void setApiKey(String apiKey)
	{
		this.apiKey = apiKey != null ? apiKey : "";
	}

	public String sendMessage(String backendUrl, ChatRequest request)
	{
		try
		{
			String json = gson.toJson(request);
			HttpRequest httpRequest = HttpRequest.newBuilder()
				.uri(URI.create(backendUrl + "/api/chat"))
				.header("Content-Type", "application/json")
				.header("X-Api-Key", apiKey)
				.POST(HttpRequest.BodyPublishers.ofString(json))
				.timeout(Duration.ofSeconds(120))
				.build();

			activeFuture = httpClient.sendAsync(httpRequest, HttpResponse.BodyHandlers.ofString());
			HttpResponse<String> response = activeFuture.join();
			activeFuture = null;

			if (response.statusCode() != 200)
			{
				log.error("Backend returned status {}: {}", response.statusCode(), response.body());
				return "Error: Backend returned status " + response.statusCode();
			}

			ChatResponse chatResponse = gson.fromJson(response.body(), ChatResponse.class);
			return chatResponse.getReply();
		}
		catch (java.util.concurrent.CancellationException e)
		{
			log.debug("Request cancelled");
			return null;
		}
		catch (Exception e)
		{
			log.error("Failed to send message to backend", e);
			return "Error: Could not reach the backend. Is it running?";
		}
	}

	/**
	 * Send a checklist to the backend for decomposition into granular micro-steps.
	 * Uses a fast LLM to break high-level steps into actionable sub-steps.
	 * Returns the decomposed checklist text, or the original on failure.
	 */
	public String decomposeChecklist(String backendUrl, String checklistText, PlayerContext playerContext)
	{
		try
		{
			ChatRequest request = new ChatRequest();
			request.setMessage(checklistText);
			request.setSessionId("decompose");
			request.setPlayerContext(playerContext);

			String json = gson.toJson(request);
			HttpRequest httpRequest = HttpRequest.newBuilder()
				.uri(URI.create(backendUrl + "/api/chat/decompose"))
				.header("Content-Type", "application/json")
				.header("X-Api-Key", apiKey)
				.POST(HttpRequest.BodyPublishers.ofString(json))
				.timeout(Duration.ofSeconds(15))
				.build();

			HttpResponse<String> response = httpClient.send(httpRequest, HttpResponse.BodyHandlers.ofString());

			if (response.statusCode() != 200)
			{
				log.warn("Decompose returned status {}", response.statusCode());
				return checklistText;
			}

			ChatResponse chatResponse = gson.fromJson(response.body(), ChatResponse.class);
			String result = chatResponse.getReply();
			if (result != null && !result.isEmpty() && result.contains("{checklist:"))
			{
				log.info("Checklist decomposed ({} -> {} chars)", checklistText.length(), result.length());
				return result;
			}

			return checklistText;
		}
		catch (Exception e)
		{
			log.warn("Failed to decompose checklist: {}", e.getMessage());
			return checklistText;
		}
	}

	public void cancel()
	{
		CompletableFuture<HttpResponse<String>> future = activeFuture;
		if (future != null)
		{
			future.cancel(true);
			activeFuture = null;
		}
	}
}

