package com.osrsassistant;

import lombok.Data;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Quest;
import net.runelite.api.QuestState;
import net.runelite.api.Skill;
import net.runelite.client.game.ItemManager;

/**
 * A verifiable condition for a checklist step.
 * Each condition must be checkable via game state — no manual-only conditions allowed.
 *
 * Supported condition types:
 *   item:Name:Qty     — player has item in inventory or equipment
 *   skill:Name:Level  — player has reached skill level
 *   quest:Name        — quest is completed
 *   chat:text         — game message contains text (sticky once triggered)
 *   loc:Name/RegionId — player is at location
 *   xp:Skill          — any XP gained in skill (sticky once triggered)
 *   xp:Skill:Amount   — cumulative XP gained >= amount since step activated (sticky)
 *   varbit:Id:Value    — game varbit equals value (server-authoritative state)
 */
@Data
public class StepCondition
{
	public enum Type
	{
		ITEM,     // item:Name:Qty — player has item in inventory or equipment
		SKILL,    // skill:Name:Level — player has reached level
		QUEST,    // quest:Name — quest is completed
		CHAT,     // chat:partial text — game message contains text
		LOCATION, // loc:RegionId or loc:Name — player is at region
		XP,       // xp:Skill or xp:Skill:Amount — XP gained since step activated
		VARBIT    // varbit:Id:Value — game varbit equals value
	}

	private final Type type;
	private final String param1;
	private final String param2;

	// For chat conditions — set to true when the message has been seen
	private boolean chatTriggered = false;

	// For XP conditions — tracks cumulative XP gained since activation
	private boolean xpActivated = false;
	private int xpBaseline = -1; // XP when step became active (-1 = not yet captured)
	private boolean xpTriggered = false;

	public StepCondition(Type type, String param1, String param2)
	{
		this.type = type;
		this.param1 = param1;
		this.param2 = param2;
	}

	/**
	 * Parse a condition string like "item:Clockwork:4" or "xp:Prayer"
	 */
	public static StepCondition parse(String condition)
	{
		if (condition == null || condition.isEmpty())
		{
			return null;
		}

		String[] parts = condition.split(":", 3);
		if (parts.length < 2)
		{
			return null;
		}

		String typeStr = parts[0].trim().toLowerCase();
		String p1 = parts[1].trim();
		String p2 = parts.length > 2 ? parts[2].trim() : null;

		switch (typeStr)
		{
			case "item":
				return new StepCondition(Type.ITEM, p1, p2 != null ? p2 : "1");
			case "skill":
				return new StepCondition(Type.SKILL, p1, p2 != null ? p2 : "1");
			case "quest":
				return new StepCondition(Type.QUEST, p1, null);
			case "chat":
				// Rejoin parts 1+ since chat text may contain colons
				String chatText = condition.substring(condition.indexOf(':') + 1).trim();
				return new StepCondition(Type.CHAT, chatText, null);
			case "loc":
				return new StepCondition(Type.LOCATION, p1, null);
			case "xp":
				// xp:Skill or xp:Skill:Amount
				return new StepCondition(Type.XP, p1, p2);
			case "varbit":
				if (p2 == null) return null; // varbit requires id:value
				return new StepCondition(Type.VARBIT, p1, p2);
			default:
				return null;
		}
	}

	/**
	 * Check if this condition is currently satisfied.
	 */
	public boolean check(Client client, ItemManager itemManager)
	{
		switch (type)
		{
			case ITEM:
				return checkItem(client, itemManager);
			case SKILL:
				return checkSkill(client);
			case QUEST:
				return checkQuest(client);
			case CHAT:
				return chatTriggered;
			case LOCATION:
				return checkLocation(client);
			case XP:
				return checkXp(client);
			case VARBIT:
				return checkVarbit(client);
			default:
				return false;
		}
	}

	/**
	 * Reset sticky state (for Undo).
	 */
	public void reset()
	{
		chatTriggered = false;
		xpActivated = false;
		xpBaseline = -1;
		xpTriggered = false;
	}

	// ---- Chat handling ----

	public void onChatMessage(String message)
	{
		if (type == Type.CHAT && !chatTriggered)
		{
			String msgLower = message.toLowerCase();
			String condLower = param1.toLowerCase();

			// Exact substring match
			if (msgLower.contains(condLower))
			{
				chatTriggered = true;
				return;
			}

			// Fuzzy match: if most key words from the condition appear in the message
			String[] words = condLower.split("\\s+");
			if (words.length >= 2)
			{
				int matched = 0;
				int meaningful = 0;
				for (String word : words)
				{
					if (isStopWord(word)) continue;
					meaningful++;
					if (msgLower.contains(word))
					{
						matched++;
					}
				}
				// Match if at least half the meaningful words are found
				if (meaningful > 0 && matched >= Math.ceil(meaningful * 0.5))
				{
					chatTriggered = true;
				}
			}
		}
	}

	private static boolean isStopWord(String word)
	{
		return word.length() <= 2 || word.equals("the") || word.equals("you")
			|| word.equals("your") || word.equals("and") || word.equals("with");
	}

	// ---- XP handling ----

	/**
	 * Called when XP changes. Captures baseline on first call, then tracks gain.
	 */
	public void onXpChanged(Skill skill, int currentXp)
	{
		if (type != Type.XP || xpTriggered) return;

		// Match skill name
		if (!skill.getName().equalsIgnoreCase(param1)) return;

		if (!xpActivated)
		{
			// First tick — capture baseline XP
			xpBaseline = currentXp;
			xpActivated = true;
			return;
		}

		int gained = currentXp - xpBaseline;
		if (gained <= 0) return;

		if (param2 == null)
		{
			// xp:Skill — any XP gain triggers completion
			xpTriggered = true;
		}
		else
		{
			// xp:Skill:Amount — cumulative gain must reach threshold
			int threshold = 1;
			try
			{
				threshold = Integer.parseInt(param2);
			}
			catch (NumberFormatException e)
			{
				threshold = 1;
			}
			if (gained >= threshold)
			{
				xpTriggered = true;
			}
		}
	}

	private boolean checkXp(Client client)
	{
		if (xpTriggered) return true;

		// If not yet activated, capture baseline now
		if (!xpActivated)
		{
			for (Skill skill : Skill.values())
			{
				if (skill.getName().equalsIgnoreCase(param1))
				{
					xpBaseline = client.getSkillExperience(skill);
					xpActivated = true;
					break;
				}
			}
		}
		return false;
	}

	// ---- Item handling ----

	private boolean checkItem(Client client, ItemManager itemManager)
	{
		int requiredQty = 1;
		try
		{
			requiredQty = Integer.parseInt(param2);
		}
		catch (NumberFormatException e)
		{
			// default to 1
		}

		int count = 0;

		// Check inventory
		count += countItemInContainer(client, itemManager, InventoryID.INVENTORY);

		// Check equipment
		count += countItemInContainer(client, itemManager, InventoryID.EQUIPMENT);

		return count >= requiredQty;
	}

	private int countItemInContainer(Client client, ItemManager itemManager, InventoryID containerId)
	{
		ItemContainer container = client.getItemContainer(containerId);
		if (container == null) return 0;

		int count = 0;
		for (Item item : container.getItems())
		{
			if (item.getId() == -1 || item.getId() == 6512) continue;
			String name = itemManager.getItemComposition(item.getId()).getName();
			if (name.equalsIgnoreCase(param1))
			{
				count += item.getQuantity();
			}
		}
		return count;
	}

	// ---- Skill handling ----

	private boolean checkSkill(Client client)
	{
		int requiredLevel = 1;
		try
		{
			requiredLevel = Integer.parseInt(param2);
		}
		catch (NumberFormatException e)
		{
			// default to 1
		}

		for (Skill skill : Skill.values())
		{
			if (skill.getName().equalsIgnoreCase(param1))
			{
				return client.getRealSkillLevel(skill) >= requiredLevel;
			}
		}
		return false;
	}

	// ---- Quest handling ----

	private boolean checkQuest(Client client)
	{
		for (Quest quest : Quest.values())
		{
			if (quest.getName().equalsIgnoreCase(param1))
			{
				return quest.getState(client) == QuestState.FINISHED;
			}
		}
		return false;
	}

	// ---- Varbit handling ----

	private boolean checkVarbit(Client client)
	{
		try
		{
			int varbitId = Integer.parseInt(param1);
			int expectedValue = Integer.parseInt(param2);
			return client.getVarbitValue(varbitId) >= expectedValue;
		}
		catch (NumberFormatException e)
		{
			return false;
		}
	}

	// ---- Location handling ----

	private static final int LOCATION_RADIUS = 30; // tiles — how close counts as "at location"

	private boolean checkLocation(Client client)
	{
		if (client.getLocalPlayer() == null)
		{
			return false;
		}

		int playerX = client.getLocalPlayer().getWorldLocation().getX();
		int playerY = client.getLocalPlayer().getWorldLocation().getY();
		int playerRegion = client.getLocalPlayer().getWorldLocation().getRegionID();

		// Try numeric region ID first
		try
		{
			int regionId = Integer.parseInt(param1);
			return playerRegion == regionId;
		}
		catch (NumberFormatException e)
		{
			// Not a number — try name-based proximity check
		}

		// Name-based: check if player is within LOCATION_RADIUS tiles of known coordinates
		int[] coords = LocationDatabase.getCoordinates(param1);
		if (coords != null)
		{
			int dx = playerX - coords[0];
			int dy = playerY - coords[1];
			return (dx * dx + dy * dy) <= (LOCATION_RADIUS * LOCATION_RADIUS);
		}

		return false;
	}
}

package com.osrsassistant;

import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.widgets.ComponentID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;

/**
 * Resolves a checklist step into a single MicroAction — the immediate next thing the player should do.
 * Runs every game tick for the active step, purely client-side logic.
 *
 * The resolver handles universal flows (inventory → bank → coins → GE) that work for any item.
 * Crafting knowledge and material breakdowns are the backend AI's job — it should generate
 * granular checklist steps rather than expecting the resolver to know recipes.
 */
@Slf4j
public class StepResolver
{
	private final Client client;
	private final ItemManager itemManager;
	private final ObjectTracker objectTracker;

	private static final int BANK_PROXIMITY = 10;
	private static final int GE_REGION_ID = 12598;

	private static final String[] BANK_OBJECTS = {"Bank booth", "Bank chest", "Grand Exchange booth", "Bank chest box"};
	private static final String[] BANK_NPCS = {"Banker"};

	public StepResolver(Client client, ItemManager itemManager, ObjectTracker objectTracker)
	{
		this.client = client;
		this.itemManager = itemManager;
		this.objectTracker = objectTracker;
	}

	/**
	 * Resolve the active step into a single MicroAction based on current game state.
	 * Returns null if the step is already complete.
	 */
	public MicroAction resolve(ChecklistStep step, PlayerContext ctx)
	{
		if (step == null || step.isCompleted())
		{
			return null;
		}

		StepCondition cond = step.getCondition();
		if (cond == null)
		{
			return resolveNoCondition(step);
		}

		switch (cond.getType())
		{
			case ITEM:
				return resolveItem(step, cond, ctx);
			case CHAT:
				return resolveChat(step, cond);
			case SKILL:
				return resolveSkill(cond);
			case QUEST:
				return resolveQuest(cond);
			case LOCATION:
				return resolveLocation(step, cond);
			default:
				return new MicroAction(step.getDescription(), MicroAction.ActionType.INFO);
		}
	}

	private MicroAction resolveNoCondition(ChecklistStep step)
	{
		// Try to find an interactable from the description in the scene
		MicroAction sceneAction = resolveFromDescription(step);
		if (sceneAction != null)
		{
			return sceneAction;
		}

		// Fall back to goto coordinates or name-based lookup
		MicroAction navAction = resolveNavigation(step);
		if (navAction != null)
		{
			return navAction;
		}

		log.debug("No navigation resolved for step: {}", step.getDescription());
		return new MicroAction(step.getDescription(), MicroAction.ActionType.INFO);
	}

	/**
	 * item:Name:Qty — Universal resolution for any item:
	 * 1. Have it in inventory? → done
	 * 2. Have it in bank? → withdraw flow
	 * 3. Don't have it → coins check → GE
	 */
	private MicroAction resolveItem(ChecklistStep step, StepCondition cond, PlayerContext ctx)
	{
		String itemName = cond.getParam1();
		int requiredQty = parseQty(cond.getParam2());

		// 1. Already have enough in inventory?
		int inventoryCount = countInInventory(itemName);
		if (inventoryCount >= requiredQty)
		{
			return null; // Step should auto-complete
		}

		int stillNeed = requiredQty - inventoryCount;

		// 2. Have it in bank? Withdraw.
		int bankCount = countInBank(itemName, ctx);
		if (bankCount > 0)
		{
			int toWithdraw = Math.min(bankCount, stillNeed);
			return resolveBankWithdraw(itemName, toWithdraw);
		}

		// 3. Don't have it anywhere — need to acquire. Check coins first.
		return resolveAcquire(itemName, stillNeed, ctx);
	}

	/**
	 * Player needs to acquire an item they don't have.
	 * Check coins before sending to GE.
	 */
	private MicroAction resolveAcquire(String itemName, int qty, PlayerContext ctx)
	{
		int coinsInInventory = countInInventory("Coins");
		int coinsInBank = countInBank("Coins", ctx);

		// No coins in inventory but have some in bank — withdraw coins first
		if (coinsInInventory == 0 && coinsInBank > 0)
		{
			return resolveBankWithdraw("Coins", 1);
		}

		// No coins anywhere
		if (coinsInInventory == 0 && coinsInBank == 0)
		{
			return new MicroAction("Need coins to buy " + itemName + formatQty(qty),
				MicroAction.ActionType.INFO);
		}

		// Have coins — go to GE
		return resolveGeBuy(itemName, qty);
	}

	/**
	 * Guide player to withdraw items from bank.
	 */
	private MicroAction resolveBankWithdraw(String itemName, int qty)
	{
		// Bank already open?
		if (isBankOpen())
		{
			return new MicroAction("Withdraw " + itemName + formatQty(qty),
				MicroAction.ActionType.INFO, null, null,
				Collections.singletonList(itemName), Collections.emptyList());
		}

		// Find nearest bank (object or NPC)
		BankResult bank = findNearestBankWithName();
		if (bank != null)
		{
			if (bank.dist > BANK_PROXIMITY)
			{
				return new MicroAction("Go to nearest bank (" + bank.dist + " tiles)",
					MicroAction.ActionType.NAVIGATE, bank.pos, null);
			}
			else
			{
				// Highlight both bank objects and NPCs
				List<String> highlightObjs = new java.util.ArrayList<>(Arrays.asList(BANK_OBJECTS));
				Collections.addAll(highlightObjs, BANK_NPCS);
				return new MicroAction("Open bank -> Withdraw " + itemName + formatQty(qty),
					MicroAction.ActionType.INTERACT, null, bank.name,
					Collections.singletonList(itemName), highlightObjs);
			}
		}

		return new MicroAction("Go to a bank to withdraw " + itemName + formatQty(qty),
			MicroAction.ActionType.INFO);
	}

	/**
	 * Guide player to buy items from GE.
	 */
	private MicroAction resolveGeBuy(String itemName, int qty)
	{
		if (isAtGe())
		{
			return new MicroAction("Buy " + itemName + formatQty(qty) + " from GE",
				MicroAction.ActionType.INFO);
		}

		WorldPoint gePoint = new WorldPoint(3165, 3487, 0);
		int dist = getDistanceTo(gePoint);
		return new MicroAction("Go to Grand Exchange (" + dist + " tiles)",
			MicroAction.ActionType.NAVIGATE, gePoint, "Grand Exchange");
	}

	/**
	 * chat:keyword — Player needs to trigger a game message.
	 */
	private MicroAction resolveChat(ChecklistStep step, StepCondition cond)
	{
		// First, try to find the interactable from the description in the scene.
		MicroAction sceneAction = resolveFromDescription(step);
		if (sceneAction != null)
		{
			return sceneAction;
		}

		// Try goto name as an object in the scene
		if (step.getGotoName() != null)
		{
			WorldPoint objPos = objectTracker.findNearest(step.getGotoName());
			if (objPos != null)
			{
				int objDist = getDistanceTo(objPos);
				if (objDist <= 5)
				{
					return new MicroAction("Interact with " + step.getGotoName(),
						MicroAction.ActionType.INTERACT, null, step.getGotoName());
				}
				else
				{
					return new MicroAction("Go to " + step.getGotoName() + " (" + objDist + " tiles)",
						MicroAction.ActionType.NAVIGATE, objPos, step.getGotoName());
				}
			}
		}

		// Nothing in scene — fall back to goto coordinates or name-based lookup
		MicroAction navAction = resolveNavigation(step);
		if (navAction != null)
		{
			return navAction;
		}

		log.debug("No navigation resolved for chat step: {} (goto={})",
			step.getDescription(), step.getGotoName());
		return new MicroAction(step.getDescription(), MicroAction.ActionType.INFO);
	}

	/**
	 * skill:Name:Level — Long-term goal, just show progress.
	 */
	private MicroAction resolveSkill(StepCondition cond)
	{
		String skillName = cond.getParam1();
		int requiredLevel = parseQty(cond.getParam2());

		int currentLevel = 1;
		for (Skill skill : Skill.values())
		{
			if (skill.getName().equalsIgnoreCase(skillName))
			{
				currentLevel = client.getRealSkillLevel(skill);
				break;
			}
		}

		if (currentLevel >= requiredLevel)
		{
			return null;
		}

		return new MicroAction("Train " + skillName + " to " + requiredLevel + " (currently " + currentLevel + ")",
			MicroAction.ActionType.INFO);
	}

	/**
	 * quest:Name — Just show the quest name.
	 */
	private MicroAction resolveQuest(StepCondition cond)
	{
		return new MicroAction("Complete " + cond.getParam1(),
			MicroAction.ActionType.INFO);
	}

	/**
	 * loc:Region — Navigate to location.
	 */
	private MicroAction resolveLocation(ChecklistStep step, StepCondition cond)
	{
		// Try goto coordinates first, then name-based fallback
		MicroAction navAction = resolveNavigation(step);
		if (navAction != null)
		{
			return navAction;
		}

		// Try the condition param as a location name
		WorldPoint resolved = lookupLocation(cond.getParam1());
		if (resolved != null)
		{
			int dist = getDistanceTo(resolved);
			if (dist > 5)
			{
				return new MicroAction("Go to " + cond.getParam1() + " (" + dist + " tiles)",
					MicroAction.ActionType.NAVIGATE, resolved, null);
			}
		}

		log.warn("Failed to resolve location step: {} (param={})", step.getDescription(), cond.getParam1());
		return new MicroAction("Go to " + cond.getParam1(), MicroAction.ActionType.INFO);
	}

	// ---- Navigation fallback ----

	/**
	 * Try to navigate using goto coordinates, or fall back to name-based location lookup.
	 * Returns null if no navigation could be resolved.
	 */
	private MicroAction resolveNavigation(ChecklistStep step)
	{
		// 1. Has explicit goto coordinates
		if (step.hasGoto())
		{
			WorldPoint target = new WorldPoint(step.getGotoX(), step.getGotoY(), 0);
			int dist = getDistanceTo(target);
			if (dist > 5)
			{
				String name = step.getGotoName() != null ? step.getGotoName() : "destination";
				return new MicroAction("Go to " + name + " (" + dist + " tiles)",
					MicroAction.ActionType.NAVIGATE, target, null);
			}
			return null; // Already there
		}

		// 2. Has goto name but no coordinates — try client-side location lookup
		if (step.getGotoName() != null)
		{
			WorldPoint resolved = lookupLocation(step.getGotoName());
			if (resolved != null)
			{
				int dist = getDistanceTo(resolved);
				if (dist > 5)
				{
					log.info("Resolved goto '{}' via client-side lookup -> ({}, {})",
						step.getGotoName(), resolved.getX(), resolved.getY());
					return new MicroAction("Go to " + step.getGotoName() + " (" + dist + " tiles)",
						MicroAction.ActionType.NAVIGATE, resolved, step.getGotoName());
				}
				return null; // Already there
			}
			else
			{
				log.warn("Failed to resolve goto '{}' — no coordinates found", step.getGotoName());
			}
		}

		// 3. No goto at all — try to extract a location name from the description
		String desc = step.getDescription();
		if (desc != null)
		{
			WorldPoint resolved = lookupLocation(desc);
			if (resolved != null)
			{
				int dist = getDistanceTo(resolved);
				if (dist > 5)
				{
					log.info("Resolved description '{}' via location lookup -> ({}, {})",
						desc, resolved.getX(), resolved.getY());
					return new MicroAction("Go to destination (" + dist + " tiles)",
						MicroAction.ActionType.NAVIGATE, resolved, null);
				}
			}
		}

		return null;
	}

	/**
	 * Look up a location name in the client-side database.
	 * Supports exact and partial matching (case-insensitive).
	 */
	public WorldPoint lookupLocation(String name)
	{
		return LocationDatabase.getWorldPoint(name);
	}

	// ---- Scene search ----

	/**
	 * Try to find an interactable object/NPC from the step description in the loaded scene.
	 * Returns NAVIGATE if found far, INTERACT if found close, null if not in scene.
	 */
	private MicroAction resolveFromDescription(ChecklistStep step)
	{
		String target = TextUtils.extractTarget(step.getDescription());
		if (target == null) return null;

		WorldPoint objPos = objectTracker.findNearest(target);
		if (objPos == null) return null;

		int dist = getDistanceTo(objPos);
		if (dist <= 5)
		{
			return new MicroAction("Interact with " + target,
				MicroAction.ActionType.INTERACT, null, target);
		}
		else
		{
			return new MicroAction("Go to " + target + " (" + dist + " tiles)",
				MicroAction.ActionType.NAVIGATE, objPos, target);
		}
	}

	// ---- Utility methods ----

	private int countInInventory(String itemName)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INVENTORY);
		if (inventory == null) return 0;

		int count = 0;
		for (Item item : inventory.getItems())
		{
			if (item.getId() == -1 || item.getId() == 6512) continue;
			String name = itemManager.getItemComposition(item.getId()).getName();
			if (name.equalsIgnoreCase(itemName))
			{
				count += item.getQuantity();
			}
		}
		return count;
	}

	private int countInBank(String itemName, PlayerContext ctx)
	{
		if (ctx == null || ctx.getBank() == null) return 0;

		int count = 0;
		for (ItemInfo bankItem : ctx.getBank())
		{
			if (bankItem.getName().equalsIgnoreCase(itemName))
			{
				count += bankItem.getQuantity();
			}
		}
		return count;
	}

	private boolean isBankOpen()
	{
		Widget bankWidget = client.getWidget(ComponentID.BANK_ITEM_CONTAINER);
		return bankWidget != null && !bankWidget.isHidden();
	}

	private static class BankResult
	{
		final WorldPoint pos;
		final String name;
		final int dist;

		BankResult(WorldPoint pos, String name, int dist)
		{
			this.pos = pos;
			this.name = name;
			this.dist = dist;
		}
	}

	private BankResult findNearestBankWithName()
	{
		WorldPoint nearest = null;
		String nearestName = null;
		int nearestDist = Integer.MAX_VALUE;

		// Search bank objects
		for (String bankName : BANK_OBJECTS)
		{
			WorldPoint pos = objectTracker.findNearestObject(bankName);
			if (pos != null)
			{
				int dist = getDistanceTo(pos);
				if (dist < nearestDist)
				{
					nearestDist = dist;
					nearest = pos;
					nearestName = bankName;
				}
			}
		}

		// Search banker NPCs (GE bankers, etc.)
		for (String npcName : BANK_NPCS)
		{
			WorldPoint pos = objectTracker.findNearestNpc(npcName);
			if (pos != null)
			{
				int dist = getDistanceTo(pos);
				if (dist < nearestDist)
				{
					nearestDist = dist;
					nearest = pos;
					nearestName = npcName;
				}
			}
		}

		if (nearest != null)
		{
			return new BankResult(nearest, nearestName, nearestDist);
		}

		// No bank in loaded scene — fall back to nearest known bank location
		return findNearestKnownBank();
	}

	private static final String[] KNOWN_BANK_KEYS = {
		"lumbridge bank", "varrock west bank", "varrock east bank",
		"falador west bank", "falador east bank", "edgeville bank",
		"draynor bank", "al kharid bank", "catherby bank",
		"seers' bank", "ardougne bank", "canifis bank", "hosidius bank"
	};

	private BankResult findNearestKnownBank()
	{
		if (client.getLocalPlayer() == null) return null;

		WorldPoint playerPos = client.getLocalPlayer().getWorldLocation();
		WorldPoint nearest = null;
		String nearestName = null;
		int nearestDist = Integer.MAX_VALUE;

		for (String key : KNOWN_BANK_KEYS)
		{
			int[] coords = LocationDatabase.getCoordinates(key);
			if (coords == null) continue;

			WorldPoint bankPos = new WorldPoint(coords[0], coords[1], 0);
			int dist = playerPos.distanceTo(bankPos);
			if (dist < nearestDist)
			{
				nearestDist = dist;
				nearest = bankPos;
				nearestName = key.substring(0, 1).toUpperCase() + key.substring(1);
			}
		}

		return nearest != null ? new BankResult(nearest, nearestName, nearestDist) : null;
	}

	private boolean isAtGe()
	{
		if (client.getLocalPlayer() == null) return false;
		return client.getLocalPlayer().getWorldLocation().getRegionID() == GE_REGION_ID;
	}

	private int getDistanceTo(WorldPoint target)
	{
		if (client.getLocalPlayer() == null) return Integer.MAX_VALUE;
		return client.getLocalPlayer().getWorldLocation().distanceTo(target);
	}

	private int parseQty(String s)
	{
		try
		{
			return Integer.parseInt(s);
		}
		catch (Exception e)
		{
			return 1;
		}
	}

	private String formatQty(int qty)
	{
		return qty > 1 ? " x" + qty : "";
	}

}

package com.osrsassistant;

import java.util.List;
import java.util.stream.Collectors;

public class SystemPromptBuilder
{
	private static final String BASE_PROMPT =
		"You are an OSRS in-game assistant (\"Old Wise Man\") in a narrow sidebar. Be extremely concise.\n\n" +
		"FORMAT — this displays in a VERY narrow sidebar (~220px wide). Optimize for readability at that width:\n" +
		"* Write short flowing sentences for simple explanations.\n" +
		"* 2-4 sentences max for simple answers.\n" +
		"* Separate distinct topics with a blank line for visual breathing room.\n" +
		"* Use **bold** for key terms. No preamble, filler, or apologies.\n" +
		"* For step-by-step guides, use numbered lists (1. 2. 3.) with one short line each.\n" +
		"* NEVER list multiple items, skills, quests, or any game entities separated by commas on one line. ALWAYS use a bulleted or numbered list with one item per line. This is critical for readability in the narrow sidebar.\n" +
		"* NEVER use em dashes (\u2014) or en dashes (\u2013). Use commas, periods, or line breaks instead.\n" +
		"* Link items/NPCs to wiki: [Name](https://oldschool.runescape.wiki/w/Name) (underscores for spaces).\n\n" +
		"WIDGET TAGS — ALWAYS use these instead of plain text when mentioning skills, items, quests, or locations:\n" +
		"* {skill:SkillName:Level} for ANY skill mention. ALWAYS use this tag, never write skill names/levels as plain text. Example: {skill:Prayer:43}, {skill:Attack:60}\n" +
		"* {item:Item Name} for ANY specific item mention. Use exact in-game name. Example: {item:Dragon bones}, {item:Abyssal whip}. NOT for categories like \"food\".\n" +
		"* {quest:Quest Name} for ANY quest mention. Exact journal name. Example: {quest:Priest in Peril}, {quest:Dragon Slayer I}\n" +
		"* {goto:Location Name:X:Y} for places and navigation. ALWAYS include OSRS world coordinates. Example: {goto:Varrock:3213:3428}, {goto:Grand Exchange:3165:3487}, {goto:Barbarian Outpost:2552:3573}. Use INSTEAD of wiki links for locations.\n" +
		"* {goto:object:Object Name} for a nearby interactable object. Example: {goto:object:Birdhouse}, {goto:object:Bank booth}. The plugin scans the scene for the nearest match.\n" +
		"* {goto:npc:NPC Name} for a nearby NPC. Example: {goto:npc:Vannaka}, {goto:npc:Banker}. The plugin finds the nearest match.\n" +
		"Use {goto:object:} or {goto:npc:} for specific interactables. Use {goto:Name:X:Y} for general areas. ALWAYS include coordinates for goto locations.\n\n" +
		"CRITICAL: Widget tags must be on the SAME line as surrounding text. They render inline. Do not put them on separate lines.\n\n" +
		"CHECKLISTS — for multi-step tasks (runs, quest guides, training plans), use groups with sequential substeps:\n" +
		"{checklist:Title}\n" +
		"{group:Group Title|goto:Location Name}\n" +
		"{step:Description|condition}\n" +
		"{step:Description|condition|goto:Location Name}\n" +
		"{/group}\n" +
		"{group:Another Group|goto:Location Name}\n" +
		"{step:Description|condition}\n" +
		"{/group}\n" +
		"{/checklist}\n\n" +
		"Rules:\n" +
		"* Groups are sequential chapters. Each group contains sequential substeps.\n" +
		"* Every {step:} MUST have a verifiable condition after the |. No manual-only steps.\n" +
		"* Supported conditions (pick the MOST reliable one for each step):\n" +
		"  - item:Name:Qty — player has item in inventory OR equipment. Example: item:Clockwork:4, item:Rune scimitar:1\n" +
		"  - xp:Skill — ANY XP gained in that skill completes the step. PREFERRED for action verification (bury bones, chop trees, cook food, craft items, smelt bars, offer bones, etc.). Example: xp:Prayer, xp:Woodcutting, xp:Cooking\n" +
		"  - xp:Skill:Amount — cumulative XP gained reaches threshold. Use for multi-action steps. Example: xp:Prayer:375 (for using ~25 bones)\n" +
		"  - varbit:Id:Value — game varbit reaches value. Use for quest step tracking when you know the varbit. Example: varbit:358:3\n" +
		"  - skill:Name:Level — player has reached skill level. Example: skill:Woodcutting:30\n" +
		"  - quest:Name — quest is completed. Example: quest:Cook's Assistant\n" +
		"  - chat:keyword — game message contains text. ONLY use as last resort when no better condition exists. Keep keywords SHORT. Example: chat:birdhouse\n" +
